#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct {
    int op, value;
} instruction;
typedef struct {
    char *name;
    instruction *code;
    size_t count;
} word;
static char *token(const char **p) {
    while (isspace((unsigned char)**p))
        (*p)++;
    if (!**p)
        return NULL;
    const char *s = *p;
    while (**p && !isspace((unsigned char)**p))
        (*p)++;
    size_t n = (size_t)(*p - s);
    char *t = (char *)malloc(n + 1);
    for (size_t i = 0; i < n; i++)
        t[i] = (char)tolower((unsigned char)s[i]);
    t[n] = 0;
    return t;
}
static void emit(instruction **c, size_t *n, instruction i) {
    *c = (instruction *)realloc(*c, (*n + 1) * sizeof(instruction));
    (*c)[(*n)++] = i;
}
static bool compile(const char *t, word *dict, size_t nd, instruction **out,
                    size_t *n) {
    for (size_t k = nd; k > 0; k--)
        if (!strcmp(t, dict[k - 1].name)) {
            for (size_t j = 0; j < dict[k - 1].count; j++)
                emit(out, n, dict[k - 1].code[j]);
            return true;
        }
    char *end;
    long value = strtol(t, &end, 10);
    if (*t && !*end) {
        instruction i = {0, (int)value};
        emit(out, n, i);
        return true;
    }
    const char *ops[] = {"+", "-", "*", "/", "dup", "drop", "swap", "over"};
    for (int k = 0; k < 8; k++)
        if (!strcmp(t, ops[k])) {
            instruction i = {k + 1, 0};
            emit(out, n, i);
            return true;
        }
    return false;
}
static forth_error run(instruction *c, size_t n, int **stack, size_t *length) {
    for (size_t j = 0; j < n; j++) {
        int op = c[j].op;
        if (op == 0) {
            *stack = (int *)realloc(*stack, (*length + 1) * sizeof(int));
            (*stack)[(*length)++] = c[j].value;
            continue;
        }
        size_t need = op <= 4 || op == 7 || op == 8 ? 2 : 1;
        if (*length < need)
            return FORTH_UNDERFLOW;
        int a = (*stack)[*length - 1], b = need == 2 ? (*stack)[*length - 2] : 0;
        if (op <= 4) {
            if (op == 4 && !a)
                return FORTH_DIVIDE_BY_ZERO;
            (*stack)[*length - 2] = op == 1   ? b + a
                                    : op == 2 ? b - a
                                    : op == 3 ? b * a
                                              : b / a;
            --*length;
        } else if (op == 6)
            --*length;
        else if (op == 7) {
            (*stack)[*length - 1] = b;
            (*stack)[*length - 2] = a;
        } else {
            *stack = (int *)realloc(*stack, (*length + 1) * sizeof(int));
            (*stack)[(*length)++] = op == 5 ? a : b;
        }
    }
    return FORTH_OK;
}
forth_error evaluate(const char *const *input, size_t count, int **stack,
                     size_t *length) {
    *stack = NULL;
    *length = 0;
    word *dict = NULL;
    size_t nd = 0;
    forth_error error = FORTH_OK;
    for (size_t line = 0; line < count && error == FORTH_OK; line++) {
        const char *p = input[line];
        char *t;
        while (error == FORTH_OK && (t = token(&p))) {
            if (!strcmp(t, ":")) {
                free(t);
                char *name = token(&p);
                char *end;
                if (!name) {
                    error = FORTH_ILLEGAL;
                    break;
                }
                strtol(name, &end, 10);
                if (!*end || !strcmp(name, ":") || !strcmp(name, ";")) {
                    free(name);
                    error = FORTH_ILLEGAL;
                    break;
                }
                word w = {name, NULL, 0};
                bool closed = false;
                while ((t = token(&p))) {
                    if (!strcmp(t, ";")) {
                        closed = true;
                        free(t);
                        break;
                    }
                    if (!compile(t, dict, nd, &w.code, &w.count))
                        error = FORTH_UNDEFINED;
                    free(t);
                    if (error != FORTH_OK)
                        break;
                }
                if (!closed && error == FORTH_OK)
                    error = FORTH_ILLEGAL;
                if (error == FORTH_OK) {
                    dict = (word *)realloc(dict, (nd + 1) * sizeof(word));
                    dict[nd++] = w;
                } else {
                    free(w.name);
                    free(w.code);
                }
            } else {
                instruction *c = NULL;
                size_t n = 0;
                if (!compile(t, dict, nd, &c, &n))
                    error = FORTH_UNDEFINED;
                else
                    error = run(c, n, stack, length);
                free(c);
                free(t);
            }
        }
    }
    for (size_t i = 0; i < nd; i++) {
        free(dict[i].name);
        free(dict[i].code);
    }
    free(dict);
    if (error != FORTH_OK) {
        free(*stack);
        *stack = NULL;
        *length = 0;
    }
    return error;
}

