#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    int *s;
    size_t n;
    const char *a[] = {": foo 5 ;", ": bar foo ;", ": foo 6 ;", "bar foo + DUP"};
    assert(evaluate(a, 4, &s, &n) == FORTH_OK && n == 2 && s[0] == 11 && s[1] == 11);
    free(s);
    const char *b[] = {"1 2 over swap drop"};
    assert(evaluate(b, 1, &s, &n) == FORTH_OK && n == 2 && s[0] == 1 && s[1] == 1);
    free(s);
    const char *c[] = {"1 +"};
    assert(evaluate(c, 1, &s, &n) == FORTH_UNDERFLOW);
    const char *d[] = {"4 0 /"};
    assert(evaluate(d, 1, &s, &n) == FORTH_DIVIDE_BY_ZERO);
    const char *e[] = {": 1 2 ;"};
    assert(evaluate(e, 1, &s, &n) == FORTH_ILLEGAL);
    const char *f[] = {"unknown"};
    assert(evaluate(f, 1, &s, &n) == FORTH_UNDEFINED);
    const char *g[] = {": DUP dup dup ;", "1 DUP"};
    assert(evaluate(g, 2, &s, &n) == FORTH_OK && n == 3);
    free(s);
    {
        const char *values[] = {"1 2 3 4 5"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 5);
        assert(actual[0] == 1);
        assert(actual[1] == 2);
        assert(actual[2] == 3);
        assert(actual[3] == 4);
        assert(actual[4] == 5);
        free(actual);
    }
    {
        const char *values[] = {"-1 -2 -3 -4 -5"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 5);
        assert(actual[0] == -1);
        assert(actual[1] == -2);
        assert(actual[2] == -3);
        assert(actual[3] == -4);
        assert(actual[4] == -5);
        free(actual);
    }
    {
        const char *values[] = {"1 2 +"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 3);
        free(actual);
    }
    {
        const char *values[] = {"1 2 3 +"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 1);
        assert(actual[1] == 5);
        free(actual);
    }
    {
        const char *values[] = {"3 4 -"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == -1);
        free(actual);
    }
    {
        const char *values[] = {"1 12 3 -"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 1);
        assert(actual[1] == 9);
        free(actual);
    }
    {
        const char *values[] = {"2 4 *"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 8);
        free(actual);
    }
    {
        const char *values[] = {"1 2 3 *"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 1);
        assert(actual[1] == 6);
        free(actual);
    }
    {
        const char *values[] = {"12 3 /"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 4);
        free(actual);
    }
    {
        const char *values[] = {"8 3 /"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 2);
        free(actual);
    }
    {
        const char *values[] = {"1 12 3 /"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 1);
        assert(actual[1] == 4);
        free(actual);
    }
    {
        const char *values[] = {"1 2 + 4 -"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == -1);
        free(actual);
    }
    {
        const char *values[] = {"2 4 * 3 /"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 2);
        free(actual);
    }
    {
        const char *values[] = {"1 3 4 * +"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 13);
        free(actual);
    }
    {
        const char *values[] = {"1 3 4 + *"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 7);
        free(actual);
    }
    {
        const char *values[] = {"1 dup"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 dup"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 3);
        assert(actual[0] == 1);
        assert(actual[1] == 2);
        assert(actual[2] == 2);
        free(actual);
    }
    {
        const char *values[] = {"1 drop"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 0);
        free(actual);
    }
    {
        const char *values[] = {"1 2 drop"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 swap"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 2);
        assert(actual[1] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 3 swap"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 3);
        assert(actual[0] == 1);
        assert(actual[1] == 3);
        assert(actual[2] == 2);
        free(actual);
    }
    {
        const char *values[] = {"1 2 over"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 3);
        assert(actual[0] == 1);
        assert(actual[1] == 2);
        assert(actual[2] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 3 over"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 4);
        assert(actual[0] == 1);
        assert(actual[1] == 2);
        assert(actual[2] == 3);
        assert(actual[3] == 2);
        free(actual);
    }
    {
        const char *values[] = {": dup-twice dup dup ;", "1 dup-twice"};
        int *actual;
        size_t n;
        assert(evaluate(values, 2, &actual, &n) == FORTH_OK && n == 3);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        assert(actual[2] == 1);
        free(actual);
    }
    {
        const char *values[] = {": countup 1 2 3 ;", "countup"};
        int *actual;
        size_t n;
        assert(evaluate(values, 2, &actual, &n) == FORTH_OK && n == 3);
        assert(actual[0] == 1);
        assert(actual[1] == 2);
        assert(actual[2] == 3);
        free(actual);
    }
    {
        const char *values[] = {": foo dup ;", ": foo dup dup ;", "1 foo"};
        int *actual;
        size_t n;
        assert(evaluate(values, 3, &actual, &n) == FORTH_OK && n == 3);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        assert(actual[2] == 1);
        free(actual);
    }
    {
        const char *values[] = {": swap dup ;", "1 swap"};
        int *actual;
        size_t n;
        assert(evaluate(values, 2, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        free(actual);
    }
    {
        const char *values[] = {": + * ;", "3 4 +"};
        int *actual;
        size_t n;
        assert(evaluate(values, 2, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 12);
        free(actual);
    }
    {
        const char *values[] = {": foo 5 ;", ": bar foo ;", ": foo 6 ;", "bar foo"};
        int *actual;
        size_t n;
        assert(evaluate(values, 4, &actual, &n) == FORTH_OK && n == 2);
        assert(actual[0] == 5);
        assert(actual[1] == 6);
        free(actual);
    }
    {
        const char *values[] = {": foo 10 ;", ": foo foo 1 + ;", "foo"};
        int *actual;
        size_t n;
        assert(evaluate(values, 3, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 11);
        free(actual);
    }
    {
        const char *values[] = {"1 DUP Dup dup"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 4);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        assert(actual[2] == 1);
        assert(actual[3] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 3 4 DROP Drop drop"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 1);
        assert(actual[0] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 SWAP 3 Swap 4 swap"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 4);
        assert(actual[0] == 2);
        assert(actual[1] == 3);
        assert(actual[2] == 4);
        assert(actual[3] == 1);
        free(actual);
    }
    {
        const char *values[] = {"1 2 OVER Over over"};
        int *actual;
        size_t n;
        assert(evaluate(values, 1, &actual, &n) == FORTH_OK && n == 5);
        assert(actual[0] == 1);
        assert(actual[1] == 2);
        assert(actual[2] == 1);
        assert(actual[3] == 2);
        assert(actual[4] == 1);
        free(actual);
    }
    {
        const char *values[] = {": foo dup ;", "1 FOO Foo foo"};
        int *actual;
        size_t n;
        assert(evaluate(values, 2, &actual, &n) == FORTH_OK && n == 4);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        assert(actual[2] == 1);
        assert(actual[3] == 1);
        free(actual);
    }
    {
        const char *values[] = {": SWAP DUP Dup dup ;", "1 swap"};
        int *actual;
        size_t n;
        assert(evaluate(values, 2, &actual, &n) == FORTH_OK && n == 4);
        assert(actual[0] == 1);
        assert(actual[1] == 1);
        assert(actual[2] == 1);
        assert(actual[3] == 1);
        free(actual);
    }
    return 0;
}
